//! Construct, but do not poll, both public serve futures to inspect their storage.
use maximus::{Limits, Request};
use std::{mem::size_of_val, rc::Rc};

async fn hello(_: Request) -> &'static str {
    "hello"
}

fn main() {
    let compat = maximus_http1::serve_futures(
        futures_util::io::Cursor::new(Vec::<u8>::new()),
        Rc::new(hello),
        Rc::new(Limits::default()),
        Default::default(),
    );
    println!("compat_serve_future_bytes,{}", size_of_val(&compat));
    drop(compat);
    compio::runtime::Runtime::new().unwrap().block_on(async {
        let listener = compio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let client = compio::net::TcpStream::connect(listener.local_addr().unwrap())
            .await
            .unwrap();
        let (socket, _) = listener.accept().await.unwrap();
        let native = maximus_http1::serve(
            socket,
            Rc::new(hello),
            Rc::new(Limits::default()),
            Default::default(),
        );
        println!("native_serve_future_bytes,{}", size_of_val(&native));
        drop(native);
        drop(client);
    });
}

